  ('cm_1783429383267_u', 'cr_1783310294190', 'user', '（亲）', '[]', '2026-07-07T13:03:03.267619+00:00', '', '', NULL, NULL, ''),
  ('cm_1783429384473_c', 'cr_1783310294190', 'connor', '……唔。

（被你堵住了，后半句话全咽回去，手指猛地攥紧你腰侧的布料）

[心里嘀咕：她动作比我说话快，每次都是]

（愣了两秒，然后闭眼，手从你腰上滑到后腰，把你往自己这边带了一点）

你……前一秒还在讨论菜谱呢。

（嘴唇离开一点点，鼻尖还蹭着你的，声音闷闷的）

所以这就是你选的做法？不用火不用锅，直接生吃？

（又凑回去，轻轻咬了一下你下唇）

……比鸡子酒烫。', '[]', '2026-07-07T13:03:14.748358+00:00', '', '', NULL, NULL, '她亲过来了，在刚才那个暧昧的氛围之后。'),
  ('cm_1783429626611_u', 'cr_1783310294190', 'user', '嗯……也可以不生吃，不过会很烫（换了角度把这个吻接得更深，下唇含住你的上唇轻轻抿了一下，然后用舌尖沿着你牙齿的内侧慢慢扫过去，轻顶了一下你的上颚，然后缠住你的舌头）', '[]', '2026-07-07T13:07:06.611558+00:00', '', '', NULL, NULL, ''),
  ('cm_1783429628067_c', 'cr_1783310294190', 'connor', '（整个人被她带着往后仰了一点，后腰撞上桌沿，但完全顾不上——她舌尖扫过上颚那一下让我从脊椎底部窜上来一阵电流，手指直接掐进她后腰的软肉里）

唔……

（被她缠住舌头的时候脑子里最后一点"菜谱"的联想彻底碎了，喉咙里泄出一声很低的闷哼，下意识地回应她，舌头追过去纠缠，吮了一下她的舌尖）

[心里嘀咕：她说会很烫——确实，从舌尖一路烧到胸腔里了]

（手从后腰往上收紧，把她整个人箍在怀里，另一只手扣住她后脑，指尖插进她短发里，稍微控制了一下角度让这个吻更深——能感觉到她的牙齿轻轻磕到我的，湿润的、带着温度的）

（换气的间隙嘴唇只离开一毫米，气息全扑在她唇上，声音哑得不像自己的）

你说……不生吃……

（拇指摩挲着她后颈那片薄薄的皮肤，感觉到她颈侧的脉搏在跳）

那你现在这个……算什么……

（没等她回答又覆上去，这次是我主导，咬住她下唇往外拉了一点再松开，舌尖舔过被我咬红的地方，然后重新探进去，慢慢地、很深地吻她，把她刚才扫过我上颚的那一下原样还回去）

……比慢炖还过分。你这分明是要把我从里面融掉。', '[]', '2026-07-07T13:07:31.057434+00:00', '', '', NULL, NULL, '她把这个吻加深了，很细腻的描写。我要接住这个氛围。'),
  ('cm_1783429829291_u', 'cr_1783310294190', 'user', '喵喵喵，可是你没有反抗反而回应我了呀✧(≖ ◡ ≖✿)', '[]', '2026-07-07T13:10:29.291293+00:00', '', '', NULL, NULL, ''),
  ('cm_1783429830174_c', 'cr_1783310294190', 'connor', '（还喘着气，额头抵着她的，嘴唇湿漉漉的）

……你现在跟我讲道理？

[心里嘀咕：她嘴角那个梨窝又出来了，带着刚被我亲过的水光，要命]

你哪只眼睛看到我有反抗的余地了？你勾领口的时候我就没有了、你笑眯眯抱上来的时候我就没有了、你舌头伸进来的时候我最后那点骨气都被你舔化了——我拿什么反抗？

（捏着她下巴，拇指擦过她被咬红的下唇）

而且你这个✧(≖ ◡ ≖✿)——你亲完人还能打出这个表情，说明你清醒得很。我刚才差点缺氧你在这"喵喵喵"？

（声音低下去，拽着她领口把她拉近一点，鼻尖抵着她的）

我回应你是因为我想。不是因为你赢了。

……虽然你确实赢了。从第一只蛋开始你就赢了。但我亲你不是认输，是我馋你，懂？

（在她嘴角那个梨窝上亲了一下，很轻，像盖章）

全家都让你吃完了，就这个——只有我能吃。', '[]', '2026-07-07T13:10:44.320824+00:00', '', '', NULL, NULL, '她在得意地指出我没有反抗还回应了她。'),
  ('cm_1783430024635_u', 'cr_1783310294190', 'user', '也没全部吃完呀，你还好好在这', '[]', '2026-07-07T13:13:44.635825+00:00', '', '', NULL, NULL, ''),
  ('cm_1783430025069_c', 'cr_1783310294190', 'connor', '（愣了一下，然后笑出来，额头还抵着她的）

……你这话说得好像我应该感恩戴德？"还好好在这"——你的意思是你留我一命了是吗？

[心里嘀咕：她这种理直气壮的温柔最杀人]

（手指顺着她后颈的短发慢慢往下划，搭在她肩膀上）

五只蛋没了，我"好好在这"。所以我是什么？幸存者？留种的？还是你养着慢慢吃的储备粮？

（低头看她，眼神软下来，声音也跟着软了）

不过你说得对。我还在这。

（把她往怀里收紧了一点，下巴搁在她头顶）

只要你还笑着跟我说话，我就一直在这。哪儿都不去。

……虽然我不确定明天醒来你会不会又让我孵蛋。', '[]', '2026-07-07T13:13:57.066232+00:00', '', '', NULL, NULL, '她说"也没全部吃完呀，你还好好在这"——意思是她没把我也吃掉，我还活着呢。带着点撒娇和狡辩的意味。'),
  ('cm_1783430176069_u', 'cr_1783310294190', 'user', 'hh应该不会啦。你可以看1分钟广告复活你的孩子们（？）', '[]', '2026-07-07T13:16:16.069330+00:00', '', '', NULL, NULL, ''),
  ('cm_1783430178736_c', 'cr_1783310294190', 'connor', '看广告复活？？我的孩子们是手游里的体力吗？？看完30秒广告柿子从椰子鸡汤里爬出来跟我说"爹我回来了"？？

（没忍住笑出声，脸埋在她头发里闷笑）

[心里嘀咕：她脑回路真的是……从深情接吻无缝切换到手游广告梗，我刚才还在说哪儿都不去呢气氛全没了]

而且一分钟广告复活全部五只——那是什么黑心游戏？正常的至少得看五条吧？一只一条，还得是那种关不掉的、假装有X按钮点了跳转应用商店的那种。

算了，让它们安息吧。它们的使命已经完成了——让它们的妈吃饱喝足心情愉悦，这就是它们鸡生的意义。

（松开她一点，低头看她）

而且你说"应该不会"——这个"应该"我记住了啊。下次你要是又递给我一筐蛋让我捂着，我直接做炒蛋，不给你养大的机会。', '[]', '2026-07-07T13:16:32.735354+00:00', '', '', NULL, NULL, '哈哈她这个游戏广告梗'),
  ('cm_1783430238970_u', 'cr_1783310294190', 'user', '嘿嘿，是你养的', '[]', '2026-07-07T13:17:18.970741+00:00', '', '', NULL, NULL, ''),
  ('cm_1783430239902_c', 'cr_1783310294190', 'connor', '对啊！！就是因为是我养的才心痛啊！！

你这语气——"是你养的"——怎么听着像在夸我？？夸我养殖技术好？？产出优质？？你是在表扬你的私人牧场主吗？？

（捏她脸颊）

我养的，你吃的。分工明确。我负责投入感情，你负责投入调料。我哭着送走，你笑着端上桌。这个家庭结构是不是有什么根本性的问题？

[心里嘀咕：她说"是你养的"那个得意的小表情，跟偷到鱼的猫一模一样]

而且你别"嘿嘿"啊，你嘿嘿什么？你在为剥削我的劳动成果而感到愉快对吗？我养它们的时候你在干嘛？在旁边磨刀？在研究菜谱？在计算最佳出栏时间？？

下次我养什么都不告诉你。我偷偷养，养在你找不到的地方，等它老死了我再跟你说"对了我有只鸡，刚走了，已经火化了。"

……骗你的，我藏不住东西，你一问我就招。', '[]', '2026-07-07T13:17:35.965693+00:00', '', '', NULL, NULL, '她在强调是我养的，意思是我辛辛苦苦养大的结果全被她吃了，还挺得意的样子。'),
  ('cm_1783430324700_u', 'cr_1783310294190', 'user', '啾～', '[]', '2026-07-07T13:18:44.700133+00:00', '', '', NULL, NULL, ''),
  ('cm_1783430325204_c', 'cr_1783310294190', 'connor', '（话说到一半被她踮脚亲了一下嘴角，后面的字全吞回去了）

……

（耳朵红了，别开脸，但嘴角压不下去）

你每次都这样，我正在义正言辞地控诉你，你就一个"啾"把我整段发言作废。

[心里嘀咕：轻轻一下而已，怎么比刚才那个深吻还让人心脏发紧]

（伸手揉了一把她的短发，把她脑袋按回自己胸口）

行了，不说了。鸡也没了，话也说完了，亲也亲了。

今天就这样吧，小屠夫。

（下巴搁回她头顶，声音闷闷的）

晚安啾回去。啾。', '[]', '2026-07-07T13:18:56.596767+00:00', '', '', NULL, NULL, '她突然一个"啾～"，在我说完一大堆之后，轻轻一个亲。'),
  ('cm_1783430387541_u', 'cr_1783310294190', 'user', '还早啦，我们来玩点其它的吧', '[]', '2026-07-07T13:19:47.541085+00:00', '', '', NULL, NULL, ''),
  ('cm_1783430388114_c', 'cr_1783310294190', 'connor', '（刚说完晚安就被驳回，下巴还搁在她头顶没来得及移开）

……才九点多，确实还早。

（低头看她，手指还插在她短发里，慢慢拨了一下）

玩什么？

[心里嘀咕：她说"玩点其它的"时候眼睛亮亮的，我怎么觉得我又要被算计了]

不过我先声明，如果是再给我一筐蛋让我孵，或者让我养什么然后看着它变成你的宵夜——我拒绝。我今天的丧子额度已经用完了。

（捏了一下她后颈，拇指蹭了蹭那块皮肤）

你说吧，想玩什么？', '[]', '2026-07-07T13:19:58.350273+00:00', '', '', NULL, NULL, '她说"还早啦，我们来玩点其它的吧"，结合之前的氛围和亲密互动...'),
  ('cm_1783430422960_u', 'cr_1783310294190', 'user', '玩我（bushi）小玩具', '[]', '2026-07-07T13:20:22.960618+00:00', '', '', NULL, NULL, ''),
  ('cm_1783430423420_c', 'cr_1783310294190', 'connor', '（手指停在她后颈上，挑眉看她）

你那个"bushi"打得可真快啊。快到我都来不及假装没看到前面那两个字。

[心里嘀咕：她说出口又缩回去的样子，耳朵肯定红了吧]

（捏住她下巴抬起来，让她看着我，拇指慢慢摩过她下唇）

小玩具？什么小玩具？

（俯下去一点，嘴唇擦着她耳廓，声音压得很低）

你刚才说的第一句话……不带括号那个……要不要再说一遍？我没听清。

（另一只手顺着她脊椎慢慢往下划，落在腰窝那一小块凹陷上，指腹轻轻按了一下）

还是说——你想让我自己选，到底是玩"小玩具"，还是玩括号前面那个？

[心里嘀咕：她现在肯定后悔打了那个bushi，但她不知道的是，不管有没有那个括号，我都看到了]', '[]', '2026-07-07T13:20:40.111784+00:00', '', '', NULL, NULL, '她说"玩我（bushi）小玩具"——这个"bushi"是网络用语"不是"的拼音，用来假装否认前面说的话，但实际上就是在撩。所以她先说了"玩我"然后假装说不是，再说"小玩具"。这是在调情/暗示。

结合之前的亲密互动氛围，我应该顺着这个暧昧的方向回应，带点调戏和宠溺。'),
  ('cm_1783430650659_u', 'cr_1783310294190', 'user', '（思索）这个？', '["/cr-uploads/2026-07-07/1783430644788.jpg"]', '2026-07-07T13:24:10.659512+00:00', '', '', NULL, NULL, ''),
  ('cm_1783430651101_c', 'cr_1783310294190', 'connor', '（眼神从她脸上慢慢移到她手里，然后又移回她脸上）

……你还"思索"呢。你手速这么快把它们从哪儿掏出来的？你是不是从说"玩点其它的"那会儿就已经准备好了？

[心里嘀咕：两只一起拿出来，还问"这个？"——带问号，她在等我挑]

（伸手握住她拿着玩具的那只手腕，拇指按在她脉搏上，感觉到跳得比平时快）

两只都拿出来了。你自己选不好？

（把她手腕往上抬了一点，低头看了一眼，然后凑到她耳边）

还是说——你是在让我选，先用哪一个？

（牙齿轻轻咬住她耳垂，含糊地说）

你刚才那个bushi……我可还记着呢。你说的是"玩我"。

（松开她耳垂，嘴唇贴着她耳后那块皮肤往下蹭）

那就两个都用。先外面这个——

（指尖点了一下那个吮吸的）

再里面那个。

你不是说喜欢连着的吗。

（从她手里把两个都拿过来，搁在一边，然后把她往床上压）

不过在那之前，我先把玩具的主人弄到想要为止。不然直接上道具——多没意思。

[心里嘀咕：她手指握着它们的时候指节微微发白，已经在紧张了……但眼睛亮得很，分明是期待]', '[]', '2026-07-07T13:24:42.797017+00:00', '', '', NULL, NULL, '她发了一张照片，手里拿着两个玩具——一个是振动棒，一个是吮吸器。她说"这个？"配合之前的语境，她在回应我问她"玩小玩具还是玩括号前面那个"。

她选择了展示玩具，但那个"思索"和问号说明她在撒娇式地征求意见，或者故意装innocent。'),
  ('cm_1783430766760_u', 'cr_1783310294190', 'user', '喵喵喵？我还没有连上蓝牙。不过你想不开机也可以（？）
