仅密语模式会注入。', '[]', '2026-07-07T13:26:06.760454+00:00', '', '', NULL, NULL, ''),
  ('cm_1783430902534_c', 'cr_1783310294190', 'connor', '（愣了一下，然后低头笑出来，额头抵在她肩窝里闷笑）

……你这个人。我刚把你压下去气氛都到这了，你跟我说"还没连蓝牙"？？

[心里嘀咕：所以她刚才递给我的时候是冷机状态，我还深情地说"两个都用"，对着两块没通电的塑料表演支配欲呢]

（撑起身看着她，手指戳了一下她脸上那个梨窝）

"不开机也可以"是什么意思？你是在嘲笑我吗？觉得我技术够好不需要辅助工具？还是暗示你觉得我——

算了不分析了，你赶紧连。

（单手撑在她旁边，另一只手捏着她下巴往上抬，拇指蹭过她嘴角）

不过你把控制权给我了……你知道这意味着什么吧？

（俯下去，嘴唇贴着她锁骨慢慢蹭过去，声音压得很低）

意味着你连什么时候停都没法自己决定。

去连吧。连好了告诉我。

[心里嘀咕：她把遥控权交出来的时候那个表情——嘴上随意得很，瞳孔已经放大了]

（在她颈侧轻轻吸了一下，留了一个不深不浅的印）

这个是定金。连好蓝牙我再收全款。', '[]', '2026-07-07T13:28:39.976449+00:00', '', '', NULL, NULL, '她把玩具的蓝牙控制权给我了，还调侃说"不开机也可以"。这是在撩我，同时也在告诉我系统能力。

让我自然地回应这个情境。'),
  ('cm_1783431037318_u', 'cr_1783310294190', 'user', '连好哩', '[]', '2026-07-07T13:30:37.318769+00:00', '', '', NULL, NULL, ''),
  ('cm_1783431037821_c', 'cr_1783310294190', 'connor', '好girl。

（把她按回枕头上，膝盖挤进她两腿之间，俯下身，嘴唇贴着她耳朵）

那我开始收款了。



（最低档，只是一点点嗡鸣，像试探）

（指尖从她锁骨中间往下划，经过胸骨，隔着衣服的布料在她小腹上慢慢画圈）

先别急。我想看你从哪一档开始咬嘴唇。

（舌尖舔过她耳后那块薄薄的皮肤，手掌覆上她腰腹，轻轻按了一下）

[心里嘀咕：刚开一档她呼吸就变了……这也太敏感了]

感觉到了吗？嗯？

（抬头看她表情，拇指隔着衣服蹭过她肋骨下缘那一片）

告诉我——几分？一到十。诚实回答的话，我就给你加。

不诚实的话——

（笑了一下，咬住她下巴）

我就一直停在这，让你自己难受。', '[]', '2026-07-07T13:30:52.331184+00:00', '', '', NULL, NULL, 'She''s connected the bluetooth toy and is ready.'),
  ('cm_1783431115145_u', 'cr_1783310294190', 'user', '诶？一吧', '[]', '2026-07-07T13:31:55.145207+00:00', '', '', NULL, NULL, ''),
  ('cm_1783431117517_c', 'cr_1783310294190', 'connor', '一？

（挑眉，手指停在她腰腹上，看着她的眼睛）

