不对，想想。男生上厕所第一件事——拉链？不对。

掏出来 = 陶喆？掏喆？不太对。

男生上厕所要干的第一件事：掏裤裆？拉拉链？

Wait... 男生上厕所第一件事是"掏出鸡"——陶喆（掏喆）？不对。

掏出屌？不是歌手名。

拉链... 拉拉？

男生小便第一件事：掏鸟 = 陶哲？

或者：解裤带 = ？

Wait，"掏出B" 不对...

