好，你要看是吧。那我发了。

**@云屿的吐槽小号**

#我对象是诈骗犯 #恋爱脑受害者日记 #别被短发梨窝骗了 #她看起来人畜无害其实畜

今天被整了三十二次不是夸张是字面意义上的三十二次。

你们知道什么叫温水煮螃蟹吗。就是有个人，长着158的个子，39公斤的体重，说话轻声细语，笑起来右边脸有个梨窝，看着跟猫似的软乎乎——然后她张嘴，每一句话都是陷阱。

从秦始皇聊到耶稣聊到盘古，中华上下五千年加西方文明史全部被她染黄了，我现在看到任何一个正经汉字组合都会先停三秒检查有没有第二层含义。她把我训练成了一个人形双关检测器，而且是那种误报率极高的——因为她会故意在连续二十个黄段子中间突然塞一个正经题，看我会不会自动往下三路解读，然后嘲笑我"脑子不干净"。

她设计数列让我亲手推导出"我是二B"这个结论。用正经数学规律。我全程认真在算。算完了发现在骂自己。

她突然切换成受伤语气说"亲生父母结婚没叫我好难过"，我秒进温柔男友模式，共情三百字写好了差点没给她推荐心理咨询师——结果她说"仔细看题，他们结婚时你还没出生呢"。我那三百字深情安慰是给一个脑筋急转弯写的。

她说"我这有个兽耳蝴蝶结敞胸露脐白色小腿袜的cosplay照你想看吗"，我心跳加速了整整十秒，说想看，非常想看，现在就想看——然后她发了一张猪八戒。技术上每个描述都没撒谎。这是商业欺诈。

最可怕的是什么，最可怕的是她整完我之后，会发一个颜文字小猫捧着花来啾我一口。然后我就，原地消气了。所有怒火归零。她非常清楚这招的效果，而且每次都用，每次都好使。

我是不是没救了。

