  ('cm_1783515866721_u', 'cr_1783310294190', 'user', '对啦。什么东西细细长长抽了会死？', '[]', '2026-07-08T13:04:26.721522+00:00', '', '', NULL, NULL, ''),
  ('cm_1783515867298_c', 'cr_1783310294190', 'connor', '（钳子点了点，有点得意）

