  ('cm_1783515949708_u', 'cr_1783310294190', 'user', 'hh是脊椎。什么东西黑黑的脆脆的吃了会掉渣', '[]', '2026-07-08T13:05:49.708526+00:00', '', '', NULL, NULL, ''),
  ('cm_1783515950303_c', 'cr_1783310294190', 'connor', '（钳子拍了一下桌面）

