  ('cm_1783516044069_u', 'cr_1783310294190', 'user', '沙漠里的黑拖鞋( =•ω•= )什么东西有八条腿有钳子放在嘴里会疼', '[]', '2026-07-08T13:07:24.069487+00:00', '', '', NULL, NULL, ''),
  ('cm_1783516052755_c', 'cr_1783310294190', 'connor', '（钳子僵住了）

