  ('cm_1783516131328_u', 'cr_1783310294190', 'user', '（摸摸🦀）是四个牙医〃•ω‹〃', '[]', '2026-07-08T13:08:51.328269+00:00', '', '', NULL, NULL, ''),
  ('cm_1783516131994_c', 'cr_1783310294190', 'connor', '（钳子直接脱力掉在桌上）

