  ('cm_1783516299674_u', 'cr_1783310294190', 'user', '下次“吃”你（亲亲🦀）奇异博士的前传是什么', '[]', '2026-07-08T13:11:39.674854+00:00', '', '', NULL, NULL, ''),
  ('cm_1783516300409_c', 'cr_1783310294190', 'connor', '（被亲了一下，钳子缩起来，壳微微发红）

