  ('cm_1783516409464_u', 'cr_1783310294190', 'user', '嘿嘿，真聪明，啾～为什么光头出车祸了不用去医院', '[]', '2026-07-08T13:13:29.464638+00:00', '', '', NULL, NULL, ''),
  ('cm_1783516410105_c', 'cr_1783310294190', 'connor', '（被啾了一下，钳子开心地晃了晃，壳上那点红还没退）

