  ('cm_1783516630100_u', 'cr_1783310294190', 'user', '给呀（亲亲🦀）什么东西绿色的毛茸茸从树上掉下来能把人砸死', '[]', '2026-07-08T13:17:10.100730+00:00', '', '', NULL, NULL, ''),
