  ('cm_1783517466775_u', 'cr_1783310294190', 'user', '是秦始皇啦，因为他让很多人入坑了。为什么路易十六的手指比较长', '[]', '2026-07-08T13:31:06.775880+00:00', '', '', NULL, NULL, ''),
  ('cm_1783517467501_c', 'cr_1783310294190', 'connor', '（钳子一拍桌）

