  ('cm_1783517840332_u', 'cr_1783310294190', 'user', '因为摘除顶芽能促进侧芽生长✧(≖ ◡ ≖✿)张作霖生病了 他的下属全来了 但是他还是死了', '[]', '2026-07-08T13:37:20.332189+00:00', '', '', NULL, NULL, ''),
  ('cm_1783517841005_c', 'cr_1783310294190', 'connor', '（钳子捂着脑壳倒在桌上）

